import type { Locale } from "./locales";
import { withIdFallback } from "@/lib/locales";
import type { PricingModel } from "./pricing";

export type ModelPriceRow = {
  label: string;
  flatkey: string;
  official?: string;
  value?: string;
};

export type ModelGeneratorField = {
  name: string;
  label: string;
  type: "select" | "number" | "text" | "boolean";
  defaultValue: string | number | boolean;
  options?: string[];
  min?: number;
  max?: number;
  help?: string;
};

export type ModelGeneratorConfig = {
  kind: "image" | "video" | "audio";
  endpoint: string;
  storageKey: string;
  fields: ModelGeneratorField[];
};

/**
 * Optional content overrides for the shared model-detail shell.  The shell is
 * intentionally data-driven: the approved Seedance prototype can define its
 * comparison, prompt, API, and FAQ content without changing the layout used
 * by text, image, and other video model pages.
 */
export type ModelLandingContent = {
  hero?: {
    title?: string;
    description?: string;
    logo?: string;
    breadcrumb?: string[];
    actionLabel?: string;
    provider?: string;
    flatkeyPrice?: string;
    referencePrice?: string;
  };
  performance?: {
    eyebrow?: string;
    title: string;
    description: string;
    metrics?: Array<{ label: string; value?: string; note: string; icon: "latency" | "requests" | "uptime" }>;
  };
  activity?: {
    eyebrow?: string;
    title: string;
    description: string;
    stats?: Array<{ label: string; value: string; unit?: string }>;
    sampleChart?: boolean;
  };
  capabilities?: Array<{ title: string; body: string }>;
  comparison?: {
    eyebrow: string;
    title: string;
    description: string;
    baselineLabel: string;
    currentLabel: string;
    rows: Array<{
      label: string;
      baseline: string;
      current: string;
    }>;
  };
  promptLibrary?: Array<{
    key: string;
    label: string;
    prompt: string;
    poster: string;
    video?: string;
    alt: string;
  }>;
  promptLibraryTitle?: string;
  promptLibraryDescription?: string;
  why?: {
    eyebrow: string;
    title: string;
    description: string;
    cards: Array<{ title: string; body: string }>;
  };
  api?: {
    eyebrow?: string;
    title: string;
    description: string;
    items: Array<{ title: string; detail: string }>;
  };
  related?: {
    eyebrow?: string;
    title: string;
    description?: string;
    cards: Array<{ href: string; name: string; description: string; asset: string }>;
  };
  faq?: Array<{ question: string; answer: string }>;
  faqTitle?: { beforeBreak: string; afterBreak: string };
};

export type ModelConfig = {
  slug: string;
  modelIds: string[];
  displayName: string;
  modelId: string;
  generator?: ModelGeneratorConfig;
  officialName: string;
  officialPrice: string;
  flatkeyPrice: string;
  estFlatkey: string;
  estOfficial: string;
  examplePrompt: string;
  priceUnit: ModelLandingKey;
  rows: ModelPriceRow[];
  seo: {
    title: string;
    description: string;
  };
  positioning: ModelLandingKey;
  useCases: ModelLandingKey[];
  faq: Array<{ question: ModelLandingKey; answer: ModelLandingKey }>;
  landingContent?: ModelLandingContent;
};

